```go
// A log entry: an offset and the raw JSON message stored there.
type entry struct {
	offset int64
	value  json.RawMessage
}

// klog is the append-only log for one key.
type klog struct {
	entries []entry // entries[i].offset == i
}

func (l *klog) append(value json.RawMessage) int64 {
	offset := int64(len(l.entries))
	l.entries = append(l.entries, entry{offset, value})
	return offset
}

// read returns every entry whose offset is >= from, in offset order.
func (l *klog) read(from int64) [][]any {
	if from < 0 {
		from = 0
	}
	i := sort.Search(len(l.entries), func(i int) bool {
		return l.entries[i].offset >= from
	})
	msgs := make([][]any, 0, len(l.entries)-i)
	for ; i < len(l.entries); i++ {
		msgs = append(msgs, []any{l.entries[i].offset, l.entries[i].value})
	}
	return msgs
}

type server struct {
	n *maelstrom.Node

	// mu guards logs and committed.
	mu        sync.Mutex
	logs      map[string]*klog
	committed map[string]int64
}

func newServer(n *maelstrom.Node) *server {
	return &server{
		n:         n,
		logs:      make(map[string]*klog),
		committed: make(map[string]int64),
	}
}

// leaderID is the node that owns all log state. Maelstrom's node ID list is
// in the same order on every node, so everybody agrees on the leader. With a
// single-node cluster the leader is always us.
func (s *server) leaderID() string {
	ids := s.n.NodeIDs()
	if len(ids) == 0 {
		return s.n.ID()
	}
	return ids[0]
}

// append stores a message on a key, returning its offset.
func (s *server) append(key string, value json.RawMessage) int64 {
	s.mu.Lock()
	defer s.mu.Unlock()
	l := s.logs[key]
	if l == nil {
		l = &klog{}
		s.logs[key] = l
	}
	return l.append(value)
}
```

