```go
func (s *server) poll(offsets map[string]int64) map[string][][]any {
	s.mu.Lock()
	defer s.mu.Unlock()
	msgs := make(map[string][][]any, len(offsets))
	for key, from := range offsets {
		l := s.logs[key]
		if l == nil {
			continue
		}
		if pairs := l.read(from); len(pairs) > 0 {
			msgs[key] = pairs
		}
	}
	return msgs
}
```

