// the response. Requests are handled one at a time under a lock, so every
// append, poll and commit observes a consistent view of the logs.
func (s *server) apply(body []byte) (map[string]any, error) {
	var req request
	if err := json.Unmarshal(body, &req); err != nil {
		return nil, fmt.Errorf("parsing request: %w", err)
	}
	switch req.Type {
	case "send":
		return map[string]any{"type": "send_ok", "offset": s.appendToLog(req.Key, req.Msg)}, nil
	case "poll":
		return map[string]any{"type": "poll_ok", "msgs": s.poll(req.Offsets)}, nil
	case "commit_offsets":
		s.commit(req.Offsets)
		return map[string]any{"type": "commit_offsets_ok"}, nil
	case "list_committed_offsets":
		return map[string]any{"type": "list_committed_offsets_ok", "offsets": s.committedOffsets(req.Keys)}, nil
	default:
		return nil, fmt.Errorf("unhandled message type %q", req.Type)
	}
}
