def parse_edn(s):
    # Minimal EDN parser for the shapes in history.txt values.
    i = [0]
    def tok():
        while i[0] < len(s) and s[i[0]] in ' \t\n,': i[0] += 1
        if i[0] >= len(s): return None
        c = s[i[0]]
        if c in '[{]': i[0] += 1; return c
        if c == ']':
            i[0] += 1; return ']'
        if c == '}':
            i[0] += 1; return '}'
        if c == '"':
            j = s.index('"', i[0]+1); v = s[i[0]+1:j]; i[0] = j+1; return ('str', v)
        m = re.match(r'[-0-9]+', s[i[0]:])
        if m:
            i[0] += m.end(); return ('num', int(m.group()))
        if s[i[0]:i[0]+3] == 'nil': i[0]+=3; return None
        m = re.match(r':[\w-]+', s[i[0]:])
        if m:
            i[0] += m.end(); return ('kw', m.group())
        raise ValueError('cannot parse at %d: %r' % (i[0], s[i[0]:i[0]+30]))
    def value():
        t = tok()
